-- Справочник комнат — разовая загрузка из выгрузки 1С (Qwert.json), не через
-- обычный REST-синхрон, как остальные сущности. guid — UID комнаты из источника,
-- room — Element без префикса "Комната ".
CREATE TABLE "rooms" (
    "id" SERIAL NOT NULL,
    "guid" TEXT NOT NULL,
    "room" TEXT NOT NULL,

    CONSTRAINT "rooms_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "rooms_guid_key" ON "rooms"("guid");

